// Package tiles implements the offline-first map-tile pipeline:
//
//   - Tile packs are plain folders of PNG files in XYZ scheme
//     (<root>/<z>/<x>/<y>.png), generated by scripts/fetch_tiles.py from
//     OpenStreetMap data and committed to this repository ("maps-requests"
//     workflow). Clients therefore never hammer tile.openstreetmap.org with
//     unlimited traffic — they fetch as many tiles as they need from our own
//     repo/release assets instead.
//
//   - The HTTP handler serves those packs from a local cache directory
//     (TILES_ROOT, default ./tiles_cache) and transparently back-fills any
//     missing tile from the upstream mirror into the cache, so each tile is
//     downloaded at most once per deployment.
package tiles

import (
	"errors"
	"fmt"
	"io"
	"math"
	"net/http"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"sync"
	"time"
)

const (
	// DefaultUpstream is the tile source used for cache back-fill. It can be
	// overridden with the TILES_UPSTREAM env var.
	DefaultUpstream = "https://tile.openstreetmap.org"
	maxZoom         = 19
	upstreamTimeout = 15 * time.Second
	// UserAgent sent to the upstream tile server (OSM usage policy requires
	// an identifiable client). Override via TILES_USER_AGENT with contact info.
	defaultUserAgent = "AlwaysTogether/1.0 (+https://github.com/always-together/always-together; maps-request-cache)"
)

var (
	errInvalidTile  = errors.New("tiles: invalid z/x/y coordinates")
	errTileTooLarge = errors.New("tiles: payload too large")
	tilePathRe      = regexp.MustCompile(`^(\d{1,2})/(\d{1,6})/(\d{1,6})\.png$`)
	manifestName    = "manifest.json"

	downloadOnce sync.Map // tile rel path -> *sync.Once (dedupe concurrent fetches)
)

// SafeJoin resolves rel ("z/x/y.png") inside root and guarantees the result
// stays within root (no traversal). Returns "" when the path is unsafe.
func SafeJoin(root, rel string) string {
	rel = strings.TrimPrefix(filepath.ToSlash(rel), "/")
	if !tilePathRe.MatchString(rel) {
		return ""
	}
	parts := strings.Split(rel, "/")
	z, _ := strconv.Atoi(parts[0])
	x, _ := strconv.Atoi(parts[1])
	y, _ := strconv.Atoi(parts[2])
	n := 1 << z
	if z < 0 || z > maxZoom || x < 0 || x >= n || y < 0 || y >= n {
		return ""
	}
	absRoot, err := filepath.Abs(root)
	if err != nil {
		return ""
	}
	p := filepath.Join(append([]string{absRoot}, parts...)...)
	if p != absRoot && !strings.HasPrefix(p, absRoot+string(os.PathSeparator)) {
		return ""
	}
	return p
}

// Exists reports whether the tile is present in the local pack/cache.
func Exists(root, rel string) bool {
	p := SafeJoin(root, rel)
	if p == "" {
		return false
	}
	st, err := os.Stat(p)
	return err == nil && !st.IsDir()
}

// Load reads a tile from the local cache.
func Load(root, rel string) ([]byte, error) {
	p := SafeJoin(root, rel)
	if p == "" {
		return nil, errInvalidTile
	}
	data, err := os.ReadFile(p)
	if err != nil {
		return nil, err
	}
	if len(data) > 2<<20 { // 2 MiB sanity bound per tile
		return nil, errTileTooLarge
	}
	return data, nil
}

// Fetch downloads one tile from the upstream mirror. Concurrent requests for
// the same tile are deduplicated so it is downloaded at most once.
func Fetch(upstream, rel string) ([]byte, error) {
	if !tilePathRe.MatchString(rel) {
		return nil, errInvalidTile
	}
	onceAny, _ := downloadOnce.LoadOrStore(rel, &sync.Once{})
	once := onceAny.(*sync.Once)

	var (
		out   []byte
		fetch error
	)
	once.Do(func() {
		url := strings.TrimRight(upstream, "/") + "/" + rel
		req, err := http.NewRequest(http.MethodGet, url, nil)
		if err != nil {
			fetch = err
			return
		}
		ua := os.Getenv("TILES_USER_AGENT")
		if ua == "" {
			ua = defaultUserAgent
		}
		req.Header.Set("User-Agent", ua)
		client := &http.Client{Timeout: upstreamTimeout}
		resp, err := client.Do(req)
		if err != nil {
			fetch = err
			return
		}
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			fetch = fmt.Errorf("tiles: upstream returned %s for %s", resp.Status, rel)
			return
		}
		body, err := io.ReadAll(io.LimitReader(resp.Body, 4<<20))
		if err != nil {
			fetch = err
			return
		}
		if !strings.HasPrefix(http.DetectContentType(body), "image/") {
			fetch = fmt.Errorf("tiles: upstream returned non-image payload for %s", rel)
			return
		}
		out = body
	})
	if fetch != nil {
		downloadOnce.Delete(rel) // allow retry later
		return nil, fetch
	}
	if out == nil {
		return nil, fmt.Errorf("tiles: empty response for %s", rel)
	}
	return out, nil
}

// Save writes tile bytes into the cache tree atomically (temp file + rename).
func Save(root, rel string, data []byte) error {
	p := SafeJoin(root, rel)
	if p == "" {
		return errInvalidTile
	}
	if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
		return err
	}
	tmp := p + ".tmp"
	if err := os.WriteFile(tmp, data, 0o644); err != nil {
		return err
	}
	return os.Rename(tmp, p)
}

// Get returns the tile bytes, using the local cache first and back-filling
// from upstream on a miss (one download per tile per process).
func Get(root, upstream, rel string) ([]byte, error) {
	if data, err := Load(root, rel); err == nil {
		return data, nil
	}
	data, err := Fetch(upstream, rel)
	if err != nil {
		return nil, err
	}
	_ = Save(root, rel, data) // cache best-effort
	return data, nil
}

// ---- Bounding-box helpers (Web Mercator XYZ) --------------------------------

// TileRange describes an inclusive rectangle of tiles at zoom z covering a
// bbox (south, west, north, east in degrees).
type TileRange struct {
	Z          int `json:"z"`
	XMin       int `json:"x_min"`
	XMax       int `json:"x_max"`
	YMin       int `json:"y_min"`
	YMax       int `json:"y_max"`
	TotalTiles int `json:"total_tiles"`
}

// Tiles enumerates every rel path ("z/x/y.png") in the range.
func (tr TileRange) Tiles() []string {
	var out []string
	for x := tr.XMin; x <= tr.XMax; x++ {
		for y := tr.YMin; y <= tr.YMax; y++ {
			out = append(out, fmt.Sprintf("%d/%d/%d.png", tr.Z, x, y))
		}
	}
	return out
}

// RangeForBBox computes the tile range covering bbox at zoom z.
func RangeForBBox(z int, s, w, n, e float64) (TileRange, error) {
	if z < 0 || z > maxZoom {
		return TileRange{}, fmt.Errorf("tiles: zoom %d out of range 0..%d", z, maxZoom)
	}
	if s > n || w > e {
		return TileRange{}, fmt.Errorf("tiles: bbox has south above north or west east of east")
	}
	num := 1 << z
	xOf := func(lon float64) int { return clamp(int((lon+180.0)/360.0*float64(num)), 0, num-1) }
	yOf := func(lat float64) int {
		latRad := lat * math.Pi / 180.0
		v := (1.0 - math.Log(math.Tan(math.Pi/4.0+latRad/2.0))/math.Pi) / 2.0
		return clamp(int(v*float64(num)), 0, num-1)
	}
	tr := TileRange{Z: z, XMin: xOf(w), XMax: xOf(e), YMin: yOf(n), YMax: yOf(s)}
	tr.TotalTiles = (tr.XMax - tr.XMin + 1) * (tr.YMax - tr.YMin + 1)
	return tr, nil
}

func clamp(v, lo, hi int) int {
	if v < lo {
		return lo
	}
	if v > hi {
		return hi
	}
	return v
}

// Manifest lists available tile packs under root (directories that contain a
// manifest.json produced by scripts/fetch_tiles.py or cmd/tilepack --seed).
func Manifest(root string) map[string]any {
	packs := []map[string]any{}
	entries, err := os.ReadDir(root)
	if err == nil {
		for _, dir := range entries {
			if !dir.IsDir() {
				continue
			}
			mp := filepath.Join(root, dir.Name(), manifestName)
			if st, err := os.Stat(mp); err == nil && !st.IsDir() {
				packs = append(packs, map[string]any{
					"name":     dir.Name(),
					"manifest": "/api/v1/maps/packs/" + dir.Name() + "/manifest",
					"bytes":    st.Size(),
				})
			}
		}
	}
	return map[string]any{"packs": packs}
}
